import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';
import {atomicJson,payloadHash} from '../execution/ledger.mjs';import {createExecutionState} from '../execution/core.mjs';
import {baalScaledLiveIdentity} from '../execution/baal-scaled-live-host-v1.mjs';import {medianDiscoveryIdentity} from '../live-paper/collector-median-discovery-v3.mjs';
