const priorCatalog=read(path.join(rt,'party-pair-root-catalog.json')),catalog={schemaVersion:1,tournamentId:tid,universeHash:universe.hash,rootCaptures:priorCatalog.rootCaptures};atomicJson(path.join(rt,'baal-scaled-rootcatalog.json'),catalog);
const startedAt=new Date().toISOString(),request={schemaVersion:1,kind:'baal_scaled_live_production_v1',ownerId:'Codex',runId:'baal-scaled-no-20261006-human',tournamentId:tid,tournamentSlug:'midterm-elections',universeHash:universe.hash,allowedMarkets:universe.exchanges.filter(m=>m.option==='YES').map(m=>m.marketId),humanAllocationSourceHash:payloadHash(human),authorityHash:payloadHash(read(path.join(rt,'paired-live-authority.json'))),catalogHash:payloadHash(catalog),codeIdentity:baalScaledLiveIdentity(process.cwd()),startedAt,entryExpiresAt:new Date(Date.parse(startedAt)+3600000).toISOString(),maximumActiveMarkets:20};
