const out={schemaVersion:1,configuredAt:startedAt,runId:request.runId,requestHash:payloadHash(request),entryExpiresAt:request.entryExpiresAt,capital:'1000.000000',maximumOrderCost:'25.000000',maximumMarketCost:'100.000000',maximumEventCost:'200.000000',maximumSharesPerOrder:100,maximumActiveMarkets:20,allowedMarkets:request.allowedMarkets.length,rootCaptures:catalog.rootCaptures.length,fees:'0.000000',newClients:0,newCredentials:0,oldHistoryPreserved:true,oldWindowsRenewed:false,liveAccountReconciliationStillRequired:true,collectorGraphFiles:Object.keys(config.codeIdentity).length};atomicJson('data/baal-scaled-live-configuration-20261006.json',out);console.log(JSON.stringify(out));
